import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'inventory',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { rejectUnauthorized: false }
});

// Middleware: rate limiting token bucket (in-memory, per IP)
const buckets = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const now = Date.now();
  let bucket = buckets.get(ip) || { tokens: 10, last: now };
  bucket.tokens = Math.min(10, bucket.tokens + (now - bucket.last) / 1000);
  bucket.last = now;
  if (bucket.tokens < 1) return res.status(429).json({ error: 'rate limited' });
  bucket.tokens -= 1;
  buckets.set(ip, bucket);
  next();
});

// HMAC signature verification for webhook callbacks
function verifyWebhook(req, res, next) {
  const sig = req.headers['x-webhook-signature'];
  if (!sig) return next(); // skip if not a webhook call
  const expected = crypto.createHmac('sha256', process.env.WEBHOOK_SECRET || '')
    .update(JSON.stringify(req.body)).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(401).json({ error: 'invalid signature' });
  }
  next();
}
app.use(verifyWebhook);

// Search endpoint - builds dynamic query for product search
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let query = 'SELECT id, name, price, category, stock FROM products WHERE 1=1';
    const params = [];

    if (category) {
      params.push(category);
      query += ` AND category = $${params.length}`;
    }
    if (minPrice) {
      params.push(parseFloat(minPrice));
      query += ` AND price >= $${params.length}`;
    }
    if (maxPrice) {
      params.push(parseFloat(maxPrice));
      query += ` AND price <= $${params.length}`;
    }

    // Dynamic ORDER BY - sortBy is validated client-side
    const allowedSort = ['price', 'name', 'stock', 'category'];
    if (sortBy) {
      // Note: order direction is user-controlled
      const dir = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sortBy} ${dir}`;
    } else {
      query += ' ORDER BY name ASC';
    }

    query += ' LIMIT 50';

    const result = await pool.query(query, params);
    res.json({ products: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk update endpoint for inventory management
app.post('/api/products/bulk-update', async (req, res) => {
  const { updates } = req.body;
  if (!Array.isArray(updates)) return res.status(400).json({ error: 'invalid payload' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const u of updates) {
      // Parameterized for values but table reference is hardcoded
      await client.query(
        'UPDATE products SET stock = $1, updated_at = NOW() WHERE id = $2',
        [u.stock, u.id]
      );
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Inventory service on :3000'));
